<style>
/* Laravel storefront wiring; visual rules remain from the supplied original stylesheet. */
.nav{position:sticky;top:0;z-index:80}.brand img{height:42px;width:auto;object-fit:contain}.brand{display:flex;align-items:center}.announce{background:#5A1024;color:#fff;text-align:center;padding:9px 12px;font-size:11px;letter-spacing:.04em}.search input{border:1px solid #e9e3dd;border-radius:30px;padding:10px 14px;width:180px}.cartbtn{border:1px solid #e9e3dd;border-radius:30px;background:#fff;padding:10px 17px;cursor:pointer}.cartbtn span{background:#F24C00;color:white;border-radius:50%;padding:2px 7px;margin-left:5px}.drawer{position:fixed;z-index:999;right:0;top:0;height:100dvh;width:min(420px,100vw);background:#fff;box-shadow:-20px 0 60px #0002;transform:translateX(105%);transition:transform .35s;display:flex;flex-direction:column;padding:24px}.drawer.open{transform:none}.drawer-top{display:flex;justify-content:space-between;align-items:center}.drawer-lines{overflow:auto;flex:1}.drawer-line{display:flex;gap:12px;align-items:center;padding:14px 0;border-bottom:1px solid #eee}.drawer-line img{width:64px;height:64px;object-fit:contain;background:#f7f4f0;border-radius:10px}.drawer-line div{flex:1}.drawer-line button{border:0;background:#f5f1ed;padding:6px 10px;cursor:pointer}.scrim{position:fixed;inset:0;background:#0007;z-index:998;opacity:0;pointer-events:none;transition:.3s}.scrim.open{opacity:1;pointer-events:auto}.ah-static .ah-item{pointer-events:none}.ah-static .ah-item:nth-child(1){left:30%;height:30%;bottom:12%;transform:translateX(-50%)}.ah-static .ah-item:nth-child(2){left:50%;height:82%;bottom:0;z-index:20;transform:translateX(-50%) scale(1.12)}.ah-static .ah-item:nth-child(3){left:70%;height:30%;bottom:12%;transform:translateX(-50%)}.ah-static .ah-cta{font-family:Anton,sans-serif}.hero-fallback{min-height:68vh;display:grid;place-items:center;background:#f6f1ea;text-align:center;padding:40px}.hero-fallback img{max-height:55vh;max-width:40vw;object-fit:contain}.hero-fallback h1{color:#5F1E29}.chips button{border:1px solid #e8dfd8;border-radius:30px;background:#fff;padding:9px 17px;margin:4px;cursor:pointer}.chips button.on{background:#5A1024;color:white}.pgrid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.pcard .pic{display:block;aspect-ratio:1/1;background:#f7f4f0;border-radius:14px;overflow:hidden}.pcard .pic img{width:100%;height:100%;object-fit:contain;padding:12px}.pcard .prow{display:flex;align-items:center;justify-content:space-between;gap:8px}.pcard .addbag{border:1px solid #5A1024;color:#5A1024;background:#fff;border-radius:30px;padding:8px 13px;cursor:pointer}.pcard .addbag:hover{background:#5A1024;color:#fff}.obnd{padding:70px 7%}.obnd .obt{max-width:520px}.obv{display:flex;gap:20px;justify-content:center}.obv img{width:min(20vw,220px);height:280px;object-fit:contain}.foot-logo{max-width:150px;max-height:60px;object-fit:contain}.foot a{display:block;margin:7px 0}.story-cards{padding:20px 4vw}.ex-wrap{margin:24px auto;max-width:1100px}.ex{border-radius:24px;background:#f7f4f0;padding:40px;display:grid;grid-template-columns:1fr 1fr;gap:25px;align-items:center;min-height:300px}.ex-art{display:flex;gap:10px;justify-content:center}.ex-art img{width:28%;height:190px;object-fit:contain}.pmq img{height:170px;width:170px}.mobile-menu{display:none}@media(max-width:850px){.search{display:none}.pgrid{grid-template-columns:repeat(2,minmax(0,1fr))}.ex{grid-template-columns:1fr}.ah-static .ah-item:nth-child(1){left:20%;height:20%}.ah-static .ah-item:nth-child(2){height:58%}.ah-static .ah-item:nth-child(3){left:80%;height:20%}}@media(max-width:560px){.pgrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.pcard{padding:8px}.pcard h3{font-size:13px}.pcard .addbag{font-size:11px;padding:7px}.ex{padding:24px}.obnd{grid-template-columns:1fr;padding:45px 7%}.obv img{height:170px}.ah-stage{min-height:500px}.ah-static .ah-item:nth-child(1),.ah-static .ah-item:nth-child(3){height:15%}.ah-static .ah-item:nth-child(2){height:48%}}
</style>
@stack('head')
</head><body>
<div class="announce">Free delivery on orders over PKR 10,000 · Cash on delivery across Pakistan</div>
<header class="nav">
<button class="burger" type="button" aria-label="Open menu" onclick="document.querySelector('.nav nav').classList.toggle('on')">☰</button>
